  seo_description = $t$Start at Casinova in seven steps: create an account, upload ID, deposit by card, load $5 to $500 with a 100% first-deposit match, play, redeem.$t$,
  tags = ARRAY[$t$getting started$t$, $t$casinova guide$t$]::text[],
  updated_at = now()
